def evaluate_E(a, b, c):
    S = a + b + c
    ab_bc_ca = a*b + b*c + c*a
    numerator = S * (ab_bc_ca + 1)
    denominator = 4 * a * b * c

    if denominator == 0:
        return None # Should not happen for positive integers

    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

