def calculate_E(k, d):
    """Calculates E(k, d) based on the derived formula."""
    if k <= 0 or d <= 0:
        return None

    # Numerator: 3 * (3k^2 + 6kd + 2d^2 + 1)
    numerator = 3 * (3 * k**2 + 6 * k * d + 2 * d**2 + 1)

    # Denominator: 4k(k+2d)
    denominator = 4 * k * (k + 2 * d)

    if denominator == 0:
        return None

    result = numerator / denominator

    if abs(result - round(result)) < 1e-9:
        return int(round(result))
    else:
        return None

